func init() {
	AdminAuditLogsTable.Annotation = &entsql.Annotation{
		Table: "admin_audit_logs",
	}
	AgentOutboundMessagesTable.ForeignKeys[0].RefTable = BotAccountsTable
	AgentOutboundMessagesTable.ForeignKeys[1].RefTable = ConversationsTable
	AgentOutboundMessagesTable.ForeignKeys[2].RefTable = MessageJobsTable
	AgentOutboundMessagesTable.Annotation = &entsql.Annotation{
		Table: "agent_outbound_messages",
	}
	AgentOutboundMessagesTable.Annotation.Checks = map[string]string{
		"agent_outbound_messages_sequence_check": "((sequence > 0))",
		"agent_outbound_messages_status_check":   "((status = ANY (ARRAY['prepared'::text, 'sending'::text, 'sent'::text, 'failed'::text, 'unknown'::text, 'denied'::text, 'cancelled'::text])))",
	}
	AgentRunBudgetsTable.ForeignKeys[0].RefTable = MessageJobsTable
	AgentRunBudgetsTable.Annotation = &entsql.Annotation{
		Table: "agent_run_budgets",
	}
	AgentSendingPoliciesTable.Annotation = &entsql.Annotation{
		Table: "agent_sending_policies",
	}
	AgentSendingPoliciesTable.Annotation.Checks = map[string]string{
		"agent_sending_policies_check":                         "((max_chars_per_message <= max_total_chars_per_run))",
		"agent_sending_policies_max_chars_per_message_check":   "((max_chars_per_message > 0))",
		"agent_sending_policies_max_messages_per_run_check":    "((max_messages_per_run > 0))",
		"agent_sending_policies_max_total_chars_per_run_check": "((max_total_chars_per_run > 0))",
		"agent_sending_policies_min_interval_ms_check":         "((min_interval_ms >= 0))",
		"agent_sending_policies_scope_type_check":              "((scope_type = ANY (ARRAY['group'::text, 'private'::text])))",
	}
	BotAccountsTable.Annotation = &entsql.Annotation{
		Table: "bot_accounts",
	}
	ContactsTable.ForeignKeys[0].RefTable = BotAccountsTable
	ContactsTable.Annotation = &entsql.Annotation{
		Table: "contacts",
	}
	ConversationsTable.ForeignKeys[0].RefTable = BotAccountsTable
	ConversationsTable.Annotation = &entsql.Annotation{
		Table: "conversations",
	}
	ConversationsTable.Annotation.Checks = map[string]string{
		"conversations_kind_check": "((kind = ANY (ARRAY['group'::text, 'private'::text])))",
	}
	GroupMembersTable.ForeignKeys[0].RefTable = BotAccountsTable
	GroupMembersTable.Annotation = &entsql.Annotation{
		Table: "group_members",
	}
	IntentDecisionsTable.ForeignKeys[0].RefTable = MessageJobsTable
	IntentDecisionsTable.Annotation = &entsql.Annotation{
		Table: "intent_decisions",
	}
	IntentDecisionsTable.Annotation.Checks = map[string]string{
		"intent_decisions_decision_check": "((decision = ANY (ARRAY['reply'::text, 'silent'::text, 'defer'::text])))",
	}
	IntentDecisionStepsTable.ForeignKeys[0].RefTable = IntentDecisionsTable
	IntentDecisionStepsTable.Annotation = &entsql.Annotation{
		Table: "intent_decision_steps",
	}
	IntentDecisionStepsTable.Annotation.Checks = map[string]string{
		"intent_decision_steps_step_index_check": "((step_index >= 0))",
	}
	IntentRuleActivationsTable.ForeignKeys[0].RefTable = IntentRulesetsTable
	IntentRuleActivationsTable.Annotation = &entsql.Annotation{
		Table: "intent_rule_activations",
	}
	IntentRuleEntriesTable.ForeignKeys[0].RefTable = IntentRulesetsTable
	IntentRuleEntriesTable.Annotation = &entsql.Annotation{
		Table: "intent_rule_entries",
	}
	IntentRulesetsTable.Annotation = &entsql.Annotation{
		Table: "intent_rulesets",
	}
	IntentRulesetsTable.Annotation.Checks = map[string]string{
		"intent_rulesets_scope_type_check": "((scope_type = ANY (ARRAY['group'::text, 'private'::text])))",
		"intent_rulesets_status_check":     "((status = ANY (ARRAY['draft'::text, 'published'::text, 'archived'::text])))",
		"intent_rulesets_version_check":    "((version > 0))",
	}
	MemoriesTable.ForeignKeys[0].RefTable = BotAccountsTable
	MemoriesTable.ForeignKeys[1].RefTable = MessagesTable
	MemoriesTable.Annotation = &entsql.Annotation{
		Table: "memories",
	}
	MemoriesTable.Annotation.Checks = map[string]string{
		"memories_status_check":     "((status = ANY (ARRAY['candidate'::text, 'active'::text, 'superseded'::text, 'deleted'::text])))",
		"memories_visibility_check": "((visibility = ANY (ARRAY['bot_shared'::text, 'group'::text, 'private_user'::text, 'conversation'::text])))",
	}
	MessagesTable.ForeignKeys[0].RefTable = AgentOutboundMessagesTable
	MessagesTable.ForeignKeys[1].RefTable = BotAccountsTable
	MessagesTable.ForeignKeys[2].RefTable = ConversationsTable
	MessagesTable.Annotation = &entsql.Annotation{
		Table: "messages",
	}
	MessagesTable.Annotation.Checks = map[string]string{
		"messages_direction_check":   "((direction = ANY (ARRAY['incoming'::text, 'outgoing'::text])))",
		"messages_sent_status_check": "(((sent_status IS NULL) OR (sent_status = ANY (ARRAY['sent'::text, 'failed'::text, 'unknown'::text]))))",
	}
	MessageJobsTable.ForeignKeys[0].RefTable = MessagesTable
	MessageJobsTable.Annotation = &entsql.Annotation{
		Table: "message_jobs",
	}
	MessageJobsTable.Annotation.Checks = map[string]string{
		"message_jobs_denied_count_check": "((denied_count >= 0))",
		"message_jobs_lease_check":        "((status = 'processing' AND claim_token IS NOT NULL AND lease_expires_at IS NOT NULL) OR (status <> 'processing' AND claim_token IS NULL AND lease_expires_at IS NULL))",
		"message_jobs_status_check":       "((status = ANY (ARRAY['pending'::text, 'processing'::text, 'done'::text, 'failed'::text, 'cancelled'::text])))",
	}
	QqGroupsTable.ForeignKeys[0].RefTable = BotAccountsTable
	QqGroupsTable.Annotation = &entsql.Annotation{
		Table: "qq_groups",
	}
	ScopePoliciesTable.ForeignKeys[0].RefTable = BotAccountsTable
	ScopePoliciesTable.Annotation = &entsql.Annotation{
		Table: "scope_policies",
	}
	ScopePoliciesTable.Annotation.Checks = map[string]string{
		"scope_policies_message_interval_ms_check": "(((message_interval_ms >= 0) AND (message_interval_ms <= 60000)))",
		"scope_policies_reply_mode_check":          "((reply_mode = ANY (ARRAY['mention_only'::text, 'intent_based'::text, 'always_reply'::text, 'observe_only'::text])))",
		"scope_policies_scope_type_check":          "((scope_type = ANY (ARRAY['group'::text, 'private'::text])))",
	}
	SystemSettingsTable.Annotation = &entsql.Annotation{
		Table: "system_settings",
	}
	SystemSettingsTable.Annotation.Checks = map[string]string{
		"system_settings_id_check":      "((id = 1))",
		"system_settings_version_check": "((version > 0))",
	}
}
